-- ── Hello World tool ─────────────────────────────────────────────────────────

data Hello = Hello { name :: Text }
  deriving (Eq, Show, Generic, JSONSchema, A.FromJSON, A.ToJSON)

instance HasFunctionObject Hello where
  getFunctionName        = "hello"
  getFunctionDescription = "Say hello to someone by name"
  getFieldDescription "name" = "The name to greet"
  getFieldDescription _      = ""

instance Tool Hello where
  data Output Hello = HelloOutput { greeting :: Text }
    deriving (Eq, Show, Generic, A.FromJSON, A.ToJSON)
  toolExec args = return $ HelloOutput $ "Hello, " <> args.name <> "!"

-- ── Extra REPL command ────────────────────────────────────────────────────────

greetCommand :: CommandSpec
greetCommand = CommandSpec
  ":greet <name>"
  (try (lexm (string ":greet") >> T.pack <$> lexm parseSessionName) >>= \n ->
     pure $ termOutput $ "Hello from the REPL, " <> n <> "!\n")

-- ── Main ──────────────────────────────────────────────────────────────────────

main :: IO ()
main = do
  config     <- readConfig
  modelName  <- lookupEnv "OPENAI_MODEL" >>= \case
    Just m  -> return (pack m)
    Nothing -> return config.model
  sessionName <- pack <$> customExecParser (prefs showHelpOnEmpty)
    (info (argument str (metavar "SESSION_NAME"))
          (fullDesc <> progDesc "hello-repl"))
  runRepl @SqliteConf
    (ToolProxy (Proxy @Hello) : defaultTools)
    [greetCommand]
    []
    sessionName
    (fromModel modelName)
    []
